Audit this YDB Go SDK handler. Does the caller's cancellation and
request deadline reach session acquisition, retries, and the query RPC?
The complete function to review is below.

```go
func loadUser(requestCtx context.Context, db *ydb.Driver, id uint64) error {
    return db.Query().Do(context.Background(), func(attemptCtx context.Context, s query.Session) error {
        res, err := s.Query(attemptCtx,
            `SELECT name FROM users WHERE id = $id`,
            query.WithParameters(ydb.ParamsBuilder().Param("$id").Uint64(id).Build()),
        )
        if err != nil { return err }
        return res.Close(attemptCtx)
    }, query.WithIdempotent())
}
```
